-- 1126: Blog post — "DP-100 Azure Data Scientist in Singapore: Course, Funding and What Replaced the Exam"
--
--       Lead-in post for WSQ - Microsoft Azure Data Scientist Associate (DP-100) (TGS-2023036642).
--       Backdated to 2025-09-26 (published, status 1). No LinkedIn / Facebook share is
--       performed: linkedin_urn carries the manual-skip sentinel and the post ships
--       already-published, so publishDue never picks it up.
--
-- Every figure below was read off the LIVE course page on 2026-08-26, not invented:
--   * Fee card: full $800.00, GST $72.00 (9%), baseline nett $472.00
--     (SG/PR 21+, 50%), MCES/SME nett $312.00 (SG 40+, 70%).
--   * Course information: 2 days / 16 hrs, Intermediate, 2 hrs assessment.
--   * Funding validity 18 Aug 2023 - 17 Aug 2027; Absentee Payroll $4.50/hr.
--   * Skills Framework: Data Analytics (ICT-BIN-4104-1.1).
--   * Exam weightings from the official study guide, skills measured as of 11 Apr 2025.
--   * NOTE: the DP-100 exam RETIRED on 1 June 2026. The post says so plainly in a
--     notice near the top, in the FAQ, and in the meta description, and it does NOT tell
--     readers to book the exam. The WSQ course itself still runs and is still funded.
--   * No exam-specific practice-exam URL exists, so the post links only the portal root
--     (never a deep link that 404s).
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line — the content HTML below is ONE line.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links. Safe to re-run.
--  * SG-only guard via @mms_instance — the CTA course is SG WSQ, absent on MY/GH.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'DP-100 Azure Data Scientist in Singapore: Course, Funding and What Replaced the Exam', 'dp-100-azure-data-scientist-singapore-guide', 'The DP-100 exam retired on 1 June 2026, but the WSQ course still runs and is still funded &mdash; $472 nett, or $312 for Singapore Citizens aged 40 and above. Here is what the course covers and what the current alternatives are.', '<div class="mmd-summary"><div class="mmd-summary-label">Summary</div><p><strong>DP-100</strong> is the Microsoft credential for data scientists moving models from notebooks into production on Azure. This guide covers what the exam measures, what the 2 days WSQ course covers, and what you pay after SkillsFuture funding &mdash; <strong>$472</strong> for Singapore Citizens and PRs aged 21 and above, or <strong>$312</strong> for Singapore Citizens aged 40 and above.</p></div><p><strong>Please note:</strong> the <strong>DP-100</strong> certification exam was retired by Microsoft on <strong>1 June 2026</strong>. Microsoft has not named a direct successor exam. The WSQ course below still runs, is still funded, and still leads to a WSQ Statement of Attainment &mdash; the skills it teaches are unchanged. What has changed is that this particular Microsoft exam can no longer be booked. <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">See the current Microsoft certification courses</a>.</p><h2>Why DP-100 is worth taking</h2><p>The gap in most data-science teams is not modelling &mdash; it is everything after the model works. Training at scale, tracking experiments, deploying an endpoint, and keeping the whole thing reproducible is a different discipline, and it is what this course covers using Azure Machine Learning.</p><ul><li><strong>It focuses on productionisation</strong>, which is where most self-taught data scientists have the widest gap.</li><li><strong>Azure Machine Learning workspaces, compute targets and pipelines</strong> are covered hands-on rather than conceptually.</li><li><strong>The skills transfer directly</strong> to MLOps roles, which command a premium in the Singapore market.</li><li><strong>It pairs naturally with AI-102</strong> if your work spans both custom models and Azure AI services.</li></ul><p>The course is mapped to the Skills Framework under <strong>Data Analytics</strong> (TSC code ICT-BIN-4104-1.1), and leads to roles such as Data Scientist, Azure Data Engineer, Azure Solution Architect, Machine Learning Engineer. <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-scientist-associate-dp-100.html">Check the funding you qualify for</a>.</p><h2>The DP-100 exam at a glance</h2><table><tbody><tr><td>Exam</td><td>DP-100: Designing and Implementing a Data Science Solution on Azure</td></tr><tr><td>Status</td><td><strong>Retired on 1 June 2026</strong></td></tr><tr><td>Replaced by</td><td>No direct successor named by Microsoft</td></tr><tr><td>Passing score</td><td>700 out of 1000 (scaled)</td></tr></tbody></table><h2>DP-100 exam domains and weightings</h2><p>These are the skills measured on the official study guide. The weightings tell you where to spend your revision time.</p><table><thead><tr><th>Skills measured</th><th>Weighting</th></tr></thead><tbody><tr><td>Design and prepare a machine learning solution</td><td>20&ndash;25%</td></tr><tr><td>Explore data and run experiments</td><td>20&ndash;25%</td></tr><tr><td>Train and deploy models</td><td>25&ndash;30%</td></tr><tr><td>Optimize language models for AI applications</td><td>25&ndash;30%</td></tr></tbody></table><p><em>Source: official Microsoft study guide, skills measured as of 11 Apr 2025.</em></p><h2>What the WSQ course covers</h2><p>The 2 days (16 hrs) <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-scientist-associate-dp-100.html"><strong>WSQ - Microsoft Azure Data Scientist Associate (DP-100)</strong></a> course is pitched at <strong>Intermediate</strong> level and is delivered in our Woodlands classroom with hands-on labs, followed by a 2 hrs assessment. The outline tracks the official objectives:</p><ol><li>LU1 Work with Data using Azure Machine Learning</li><li>LU2 Manage Data Science Projects and Customize Data Models</li><li>LU3 Run Data Model and Manage Capacity</li><li>LU4 Recommendations for Model Deployment</li></ol><h2>Practise what you learn</h2><p>Course participants get access to our <a href="https://exams.tertiaryinfotech.com/practice-exams">Practice Exam Portal</a>, which carries timed mock papers across the Microsoft certification track. Rehearsing under exam conditions is the single best predictor of a first-time pass.</p><h2>What you actually pay: funding for DP-100 training</h2><p>The full fee is $800 before GST. As an SWDA-funded WSQ course, the subsidy depends on your citizenship, age and who is sponsoring you:</p><table><thead><tr><th>Who you are</th><th>Subsidy</th><th>You pay (incl. GST)</th></tr></thead><tbody><tr><td>Non-funded / international participants</td><td>&ndash;</td><td>$872</td></tr><tr><td>Singapore Citizen or PR, aged 21 and above</td><td>50%</td><td><strong>$472</strong></td></tr><tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td>70%</td><td><strong>$312</strong></td></tr></tbody></table><p><em>GST of $72 is charged at 9% on the full course fee of $800, as required for SWDA-funded courses &mdash; the subsidy applies to the course fee, not the tax.</em></p><p>Funding for this course is valid from <strong>18 Aug 2023</strong> to <strong>17 Aug 2027</strong>. You must register and complete the course within that window to qualify.</p><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">1. SkillsFuture Credit (SFC)</summary><div class="mmd-faq-a"><p>Singaporeans aged 25 and above have an opening SkillsFuture Credit of $500 plus any top-ups, and those aged 40 and above received a $4,000 Mid-Career top-up. Credit can offset the fee payable after subsidy, though the Mid-Career top-up cannot be used on this course. <a href="https://www.tertiarycourses.com.sg/how-to-claim-skillsfuture-credit.html">How to claim SkillsFuture Credit</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">2. SkillsFuture Enterprise Credit (SFEC)</summary><div class="mmd-faq-a"><p>Eligible employers can draw on SFEC to cover out-of-pocket costs when sponsoring staff. See our <a href="https://www.tertiarycourses.com.sg/sfec.html">SFEC guide</a> for who qualifies and how to claim.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">3. PSEA</summary><div class="mmd-faq-a"><p>Singapore Citizens can use Post-Secondary Education Account funds to offset the fee payable after subsidy. This course carries the PSEA tag, so it is eligible.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">4. UTAP</summary><div class="mmd-faq-a"><p>NTUC members can claim 50% of the unfunded fee under UTAP, capped at $250 a year, or $500 a year for members aged 40 and above. See the <a href="https://www.tertiarycourses.com.sg/utap.html">UTAP guide</a>.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">5. Absentee Payroll</summary><div class="mmd-faq-a"><p>Employers sponsoring staff can claim Absentee Payroll at $4.50 an hour, capped at $100,000 per enterprise per year, for the hours staff spend in training.</p></div></details></div><p><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-scientist-associate-dp-100.html"><strong>See the live fee breakdown for your profile &rarr;</strong></a></p><h2>How to get started</h2><ol><li><strong>Register for the 2 days WSQ course.</strong> Pick an intake on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-scientist-associate-dp-100.html">course page</a> and apply your funding at checkout.</li><li><strong>Attend and complete the assessment.</strong> You need at least 75% attendance and a pass in the 2 hrs assessment to receive your WSQ Statement of Attainment.</li><li><strong>Rehearse on the practice exams</strong> until you are consistently clearing the pass mark under timed conditions.</li></ol><h2>Where to go after DP-100</h2><p><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-ai-engineer-associate-ai-102-training.html">AI-102, the Azure AI Engineer Associate</a>, is the current, actively maintained Azure AI credential and the natural next step. For the data platform underneath, <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-fundamentals-dp-900.html">DP-900</a> covers the fundamentals. Browse the full <a href="https://www.tertiarycourses.com.sg/microsoft-certifications-exams.html">Microsoft certification course catalogue</a> to plan the next rung.</p><h2>Frequently asked questions</h2><div class="mmd-faq"><details class="mmd-faq-item"><summary class="mmd-faq-q">Is the DP-100 exam still available?</summary><div class="mmd-faq-a"><p>No. Microsoft retired the DP-100 exam on 1 June 2026 and has not named a direct successor. The course still runs, remains WSQ-funded, and still leads to a WSQ Statement of Attainment &mdash; the Azure Machine Learning skills it teaches are unaffected.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Should I take this or AI-102?</summary><div class="mmd-faq-a"><p>If you want a current Microsoft certification badge, <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-azure-ai-engineer-associate-ai-102-training.html">AI-102</a> is the actively maintained Azure AI credential. Take this course if your goal is specifically Azure Machine Learning skills for building and deploying custom models.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need Python experience?</summary><div class="mmd-faq-a"><p>Yes. This is an intermediate-level course and assumes working familiarity with Python and core machine-learning concepts.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">Do I need my own Azure subscription?</summary><div class="mmd-faq-a"><p>You will need to sign up for an Azure account, which requires a credit card. Free-tier credits generally cover the lab work.</p></div></details><details class="mmd-faq-item"><summary class="mmd-faq-q">What funding is available?</summary><div class="mmd-faq-a"><p>Singapore Citizens and PRs aged 21 and above get 50% subsidy, rising to 70% for Citizens aged 40 and above, plus SkillsFuture Credit, PSEA and UTAP.</p></div></details></div><h2>Register for Azure Data Scientist training</h2><p>Seats are limited and classes fill ahead of each intake. View upcoming dates and reserve your place on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-azure-data-scientist-associate-dp-100.html"><strong>WSQ - Microsoft Azure Data Scientist Associate (DP-100)</strong></a> course page, or call us on +65 6100 0613 if you would like your funding worked out first.</p>', 'Tertiary Infotech Academy', 1, '2025-09-26', 'TGS-2023036642', 'TGS-2023036642', 'DP-100 Course Singapore | Azure Data Scientist | WSQ Funding', 'DP-100 Azure Data Scientist in Singapore. The DP-100 exam retired on 1 June 2026; the WSQ course still runs from $312 nett after funding. Full details and current alternatives.', 'dp-100 course singapore, azure data scientist certification, dp-100 exam, wsq microsoft course, skillsfuture microsoft certification, microsoft certification singapore, dp-100 funding, dp-100 training singapore', 'manual-skip-no-share', '2025-09-26 09:00:00', '2025-09-26 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'dp-100-azure-data-scientist-singapore-guide');

