INSERT INTO `tag` (`name`, `status`) SELECT 'Microsoft', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Microsoft') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Azure', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Azure') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'DP-100', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'DP-100') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Machine Learning', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Machine Learning') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'WSQ') x);

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'dp-100-azure-data-scientist-singapore-guide');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @post_id, `tag_id` FROM `tag` WHERE @post_id IS NOT NULL AND `name` IN ('Microsoft', 'Azure', 'DP-100', 'Machine Learning', 'WSQ');

-- Seed the like count so the post does not ship showing "0 Likes" (same `likes < 100` guard
